// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {IHooks} from "v4-core/src/interfaces/IHooks.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {PoolId} from "v4-core/src/types/PoolId.sol";
import {Currency} from "v4-core/src/types/Currency.sol";
import {ModifyLiquidityParams} from "v4-core/src/types/PoolOperation.sol";
import {TickMath} from "v4-core/src/libraries/TickMath.sol";
import {StateLibrary} from "v4-core/src/libraries/StateLibrary.sol";
import {Hooks} from "v4-core/src/libraries/Hooks.sol";
import {PegFeeHook} from "src/PegFeeHook.sol";

contract Tok is ERC20 {
    uint8 private immutable _d;

    constructor(string memory n, uint8 d) ERC20(n, n) {
        _d = d;
        _mint(msg.sender, 1e40);
    }

    function decimals() public view override returns (uint8) {
        return _d;
    }
}

/// @dev Stands in for the PoolManager: answers `extsload` (all the hook reads through StateLibrary) from a
/// map, and calls the hook's `beforeAddLiquidity` as the real manager does on every add.
contract ManagerStandIn {
    mapping(bytes32 => bytes32) private _s;

    function store(bytes32 slot, bytes32 v) external {
        _s[slot] = v;
    }

    function extsload(bytes32 slot) external view returns (bytes32) {
        return _s[slot];
    }

    function add(PegFeeHook hook, PoolKey calldata key, ModifyLiquidityParams calldata p) external returns (bytes4) {
        return hook.beforeAddLiquidity(msg.sender, key, p, "");
    }
}

/// @notice Round-3 finding: the empty-pool guard (`beforeAddLiquidity` refuses an add while `getLiquidity == 0`
/// and the price is off the band) is switched off by ONE wei of in-range liquidity, so the first real deposit
/// can still land at a moved price — the exact thing the guard was added for in round 2.
///
/// Reproduced against the real v4 PoolManager (compiled with its solmate dependency vendored, which this
/// repository's lib/ lacks, so the state is replayed here through a stand-in that serves the same storage):
///   1. pool opened at $1, no liquidity; attacker adds liquidityDelta = 1, full range  -> allowed (in band)
///   2. attacker swaps zeroForOne exact-in with sqrtPriceLimit at $0.85 against that 1 wei of liquidity:
///      spent 1,084,670 wei imdUSD (1e-12 imdUSD) and 1 wei USDC; pool price now $0.85, getLiquidity == 1
///   3. the LP's planned first deposit, $0.95–$1.05 range, liquidityDelta 1e18: `beforeAddLiquidity` sees
///      liquidity 1, skips the band check, and the deposit lands one-sided (all imdUSD) at $0.85.
/// Expected: the add in step 3 is refused (as it is when liquidity is exactly 0). Actual: it goes through.
contract EmptyPoolGuardBypassTest is Test {
    address constant TREASURY = address(0x7EA5);

    ManagerStandIn pm;
    PegFeeHook hook;
    PoolKey key;
    bytes32 stateSlot;

    function setUp() public {
        pm = new ManagerStandIn();
        Tok imdusd = new Tok("imdUSD", 18);
        Tok usdc = new Tok("USDC", 6);
        hook = _deployHook(address(imdusd), address(usdc));
        (address c0, address c1) =
            hook.stableIsToken0() ? (address(imdusd), address(usdc)) : (address(usdc), address(imdusd));
        key = PoolKey(Currency.wrap(c0), Currency.wrap(c1), 100, 1, IHooks(address(hook)));
        PoolId id = key.toId();
        stateSlot = keccak256(abi.encodePacked(PoolId.unwrap(id), StateLibrary.POOLS_SLOT));
    }

    function _deployHook(address stable, address quote) private returns (PegFeeHook h) {
        bytes memory init = abi.encodePacked(type(PegFeeHook).creationCode, abi.encode(pm, stable, quote, TREASURY));
        bytes32 initHash = keccak256(init);
        uint160 flags = Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_ADD_LIQUIDITY_FLAG | Hooks.AFTER_SWAP_FLAG
            | Hooks.AFTER_SWAP_RETURNS_DELTA_FLAG;
        for (uint256 salt;; ++salt) {
            address a = vm.computeCreate2Address(bytes32(salt), initHash, address(this));
            if (uint160(a) & Hooks.ALL_HOOK_MASK == flags) {
                h = new PegFeeHook{salt: bytes32(salt)}(IPoolManager(address(pm)), stable, quote, TREASURY);
                require(address(h) == a);
                return h;
            }
        }
    }

    function _sqrtAt(uint256 priceE18) private view returns (uint160) {
        uint256 rel = hook.stableIsToken0() ? priceE18 : 1e36 / priceE18;
        uint256 x = rel * 1e18;
        uint256 y = x;
        uint256 z = (x + 1) / 2;
        while (z < y) (y, z) = (z, (x / z + z) / 2);
        return uint160(hook.pegSqrtPriceX96() * y / 1e18);
    }

    /// @dev Pool state after step 2 above: price $0.85, active liquidity `liq`.
    function _poolAt(uint256 priceE18, uint128 liq) private {
        pm.store(stateSlot, bytes32(uint256(_sqrtAt(priceE18)))); // slot0: sqrtPriceX96 in the low 160 bits
        pm.store(bytes32(uint256(stateSlot) + StateLibrary.LIQUIDITY_OFFSET), bytes32(uint256(liq)));
    }

    function test_oneWeiOfLiquiditySwitchesTheEmptyPoolGuardOff() public {
        int24 lower = TickMath.getTickAtSqrtPrice(_sqrtAt(hook.stableIsToken0() ? 0.95e18 : 1.05e18));
        int24 upper = TickMath.getTickAtSqrtPrice(_sqrtAt(hook.stableIsToken0() ? 1.05e18 : 0.95e18));
        ModifyLiquidityParams memory firstRealDeposit = ModifyLiquidityParams(lower, upper, 1e18, 0);

        // Sanity: with NO liquidity the guard works — $0.85 is refused.
        _poolAt(0.85e18, 0);
        vm.expectRevert(PegFeeHook.EmptyPoolOffPeg.selector);
        pm.add(hook, key, firstRealDeposit);

        // The attacker's 1 wei of liquidity (added at $1, then dragged to $0.85 for ~1e-12 imdUSD): the pool
        // is as empty as makes no difference, the price is 15% off the peg, and the add must still be refused.
        _poolAt(0.85e18, 1);
        (bool ok,) = address(pm).call(abi.encodeCall(ManagerStandIn.add, (hook, key, firstRealDeposit)));
        assertFalse(ok, "1 wei of active liquidity let the first real deposit land at $0.85");
    }
}
